+extension GRDBStorageActor: SummaryReadRepository {
+    public func getSummary(for recordingId: RecordingID) async throws -> MeetingSummary? {
+        try dbPool.read { db in
+            guard let row = try Row.fetchOne(db, sql: GRDBSQL.selectSummary, arguments: [recordingId.rawValue]),
+                  let json: String = row["summary_json"],
+                  let data = json.data(using: .utf8) else { return nil }
+            let decoder = JSONDecoder()
+            decoder.dateDecodingStrategy = .iso8601
+            return try decoder.decode(MeetingSummary.self, from: data)
+        }
