+                    ids.insert(RecordingID(raw))
+                }
+            }
+            return ids
+        }
+    }
+}
+
+extension GRDBStorageActor: SummaryWriteRepository {
+    public func saveSummary(for recordingId: RecordingID, summary: MeetingSummary) async throws {
+        do {
+            let encoder = JSONEncoder()
+            encoder.dateEncodingStrategy = .iso8601
+            let json = try String(data: encoder.encode(summary), encoding: .utf8) ?? "{}"
+            let iso = Self.formatISO8601(summary.generatedAt)
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.upsertSummary, arguments: [recordingId.rawValue, json, iso])
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
