+
+extension GRDBStorageActor: TranscriptReadRepository {
+    public func searchTranscripts(query: String, limit: Int?, offset: Int?) async throws -> [RecordingSummary] {
+        do {
+            return try dbPool.read { db in
+                let escaped = query
+                    .replacingOccurrences(of: "\\", with: "\\\\")
+                    .replacingOccurrences(of: "%", with: "\\%")
+                    .replacingOccurrences(of: "_", with: "\\_")
+                let rows = try Row.fetchAll(db, sql: GRDBSQL.searchTranscripts, arguments: ["%\(escaped)%"])
+                return rows.compactMap { row -> RecordingSummary? in
+                    guard let id: String = row["id"],
+                          let dateStr: String = row["recorded_at"],
+                          let dur: Double = row["duration"],
+                          let wc: Int = row["word_count"],
+                          let date = Self.parseISO8601(dateStr) else { return nil }
+                    return RecordingSummary(
+                        id: RecordingID(id), date: date, duration: dur, wordCount: wc
+                    )
+                }
+            }
+        } catch {
+            throw StorageError.searchFailed(underlying: error)
+        }
+    }
+
+    public func getTranscriptDraft(for id: RecordingID) async throws -> String? {
+        try dbPool.read { db in
+            let row = try Row.fetchOne(db, sql: GRDBSQL.selectTranscriptDraft, arguments: [id.rawValue])
+            return row?["transcript_draft"] as String?
+        }
+    }
+}
+
+extension GRDBStorageActor: TranscriptWriteRepository {
+    public func updateTranscript(id: RecordingID, transcript: TranscriptionResult) async throws {
+        try guardExists(id: id)
+        let wc = transcript.fullText.split(separator: " ").count
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.updateTranscript, arguments: [
+                    transcript.fullText, transcript.modelId.rawValue,
+                    transcript.processingTime, transcript.computeUnit.rawValue,
+                    wc, id.rawValue,
+                ])
+            }
+        } catch let err as StorageError {
+            throw err
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+    }
+
+    public func saveDraftTranscript(draftText: String, for id: RecordingID) async throws {
+        do {
+            try dbPool.write { db in
+                try db.execute(sql: GRDBSQL.saveDraftTranscript, arguments: [draftText, id.rawValue])
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+    }
+}
+
+// MARK: - WordTimingsWriteRepository
+
+extension GRDBStorageActor: WordTimingsWriteRepository {
+    public func saveWordTimings(recordingId: RecordingID, segments: [TranscriptionSegment]) async throws {
+        let encoder = JSONEncoder()
+        do {
+            try dbPool.write { db in
+                for (idx, segment) in segments.enumerated() {
+                    let jsonString: String? = try Self.encodeWordTimings(segment.wordTimings, encoder: encoder)
+                    try db.execute(sql: GRDBSQL.saveWordTimings, arguments: [jsonString, recordingId.rawValue, idx])
+                }
+            }
+        } catch {
+            throw StorageError.writeFailed(underlying: error)
+        }
+    }
+
+    private static func encodeWordTimings(_ timings: [WordTimestamp]?, encoder: JSONEncoder) throws -> String? {
+        guard let timings else { return nil }
+        let data = try encoder.encode(timings)
+        guard data.count <= wordTimingsMaxBytes else { return nil }
+        return String(data: data, encoding: .utf8)
+    }
+}
