import Domain
import SwiftUI

extension SettingsView {
    var generalTab: some View {
        Form {
            appearanceSection
            autoRecordingSection
            audioSourceSection
            meetingTypeSection
            privacySection
            exportSection
            storageSection
            deleteAllDataSection
        }
        .padding()
        .task { await viewModel.loadStorageInfo() }
    }

    private var appearanceSection: some View {
        Section("Appearance") {
            Picker("UI Style", selection: $viewModel.uiTheme) {
                Text("Classic").tag(UITheme.classic)
                Text("Broadsheet").tag(UITheme.broadsheet)
            }
            .pickerStyle(.segmented)
            .onChange(of: viewModel.uiTheme) { viewModel.saveTheme() }
        }
    }

    private var autoRecordingSection: some View {
        Section("Auto-Recording") {
            Toggle("Auto-detect meetings", isOn: $viewModel.autoRecordEnabled)
            HStack {
                Text("Start delay")
                Slider(value: $viewModel.startDebounce, in: 1 ... 10, step: 1)
                    .accessibilityLabel("Recording start delay in seconds")
                Text("\(Int(viewModel.startDebounce))s")
            }
            HStack {
                Text("Stop delay")
                Slider(value: $viewModel.stopDebounce, in: 5 ... 30, step: 1)
                    .accessibilityLabel("Recording stop delay in seconds")
                Text("\(Int(viewModel.stopDebounce))s")
            }
        }
    }

    private var audioSourceSection: some View {
        Section("Audio Source") {
            Toggle("Capture all system audio (global tap)", isOn: $viewModel.tapAllAudio)
                .onChange(of: viewModel.tapAllAudio) {
                    Task { await viewModel.saveAudioDeviceSelection() }
                }
            Toggle("Echo cancellation", isOn: $viewModel.echoCancellationEnabled)
                .onChange(of: viewModel.echoCancellationEnabled) {
                    Task { await viewModel.saveAudioDeviceSelection() }
                }
            Text(
                "Global tap captures every app's audio regardless of output device" +
                    " — recommended when switching between headphones, speakers, or DACs during meetings."
            )
            .font(.caption)
            .foregroundStyle(.secondary)

            if !viewModel.tapAllAudio {
                Picker("Output Device", selection: $viewModel.selectedOutputDeviceID) {
                    ForEach(viewModel.outputDevices, id: \.id) { device in
                        Text("\(device.name) (\(Int(device.sampleRate)) Hz)").tag(device.id)
                    }
                }
                .pickerStyle(.menu)
            }
            Picker("Input Device (Microphone)", selection: $viewModel.selectedInputDeviceID) {
                ForEach(viewModel.inputDevices, id: \.id) { device in
                    Text("\(device.name) (\(Int(device.sampleRate)) Hz)").tag(device.id)
                }
            }
            .pickerStyle(.menu)
            HStack {
                Spacer()
                Button("Apply") {
                    Task { await viewModel.saveAudioDeviceSelection() }
                }
                .buttonStyle(.borderedProminent)
                Spacer()
            }
            .padding(.top, 8)
        }
    }

    private var meetingTypeSection: some View {
        Section("Meeting Type") {
            Picker("Default type", selection: $viewModel.defaultMeetingType) {
                ForEach(MeetingType.allCases, id: \.self) { type in
                    Text(type.rawValue).tag(type)
                }
            }
        }
    }

    private var privacySection: some View {
        Section("Privacy") {
            Picker("Screen protection", selection: $viewModel.privacyMode) {
                Text("Off").tag(PrivacyMode.off)
                Text("During meetings").tag(PrivacyMode.meetings)
                Text("Always").tag(PrivacyMode.always)
            }
            .pickerStyle(.segmented)
            .onChange(of: viewModel.privacyMode) { viewModel.applyPrivacyMode() }
            Text(viewModel.privacyMode.settingCaption)
                .font(.caption)
                .foregroundStyle(.secondary)
        }
    }

    private var exportSection: some View {
        Section("Export") {
            Picker("Default format", selection: $viewModel.defaultExportFormat) {
                ForEach(ShareFormat.allCases, id: \.self) { fmt in
                    Text(fmt.rawValue.uppercased()).tag(fmt)
                }
            }
        }
    }

}

// Delete All Data section rows live in SettingsViewDeleteAllSection.swift
// (binds to viewModel.deleteAllConfirmationText — see SettingsViewDeleteAllSection.swift)
// Storage section rows live in SettingsViewStorageSection.swift

