import Domain
import Foundation
import Observation

public extension Notification.Name {
    static let themeChanged = Notification.Name("app.the-record.themeChanged")
    static let privacyModeChanged = Notification.Name("app.the-record.privacyModeChanged")
    static let recordingStarted = Notification.Name("app.the-record.recordingStarted")
    static let recordingStopped = Notification.Name("app.the-record.recordingStopped")
    static let showLogs = Notification.Name("app.the-record.showLogs")
    static let engineChanged = Notification.Name("app.the-record.engineChanged")
    static let archivePassEnabledChanged = Notification.Name("app.the-record.archivePassEnabledChanged")
}

@Observable
@MainActor
public final class SettingsViewModel {
    // SSOT: These properties now shadow or proxy the AppState.settings, 
    // with local fallbacks for standalone usage/testing.
    private var _uiTheme: UITheme = .default
    public var uiTheme: UITheme {
        get { appState?.settings.uiTheme ?? _uiTheme }
        set { 
            if let appState { appState.settings.uiTheme = newValue }
            _uiTheme = newValue
            saveTheme()
        }
    }

    private var _defaultEngine: TranscriptionEngineKey = TranscriptionConfig.default.defaultEngine
    public var defaultEngine: TranscriptionEngineKey {
        get { appState?.settings.defaultEngine ?? _defaultEngine }
        set { 
            if let appState { appState.settings.defaultEngine = newValue }
            _defaultEngine = newValue
            saveEngine()
        }
    }

    private var _privacyMode: PrivacyMode = AppConfig.default.privacyMode
    public var privacyMode: PrivacyMode {
        get { appState?.settings.privacyMode ?? _privacyMode }
        set { 
            if let appState { appState.settings.privacyMode = newValue }
            _privacyMode = newValue
            applyPrivacyMode()
        }
    }

    private var _archivePassEnabled: Bool = true
    public var archivePassEnabled: Bool {
        get { appState?.settings.archivePassEnabled ?? _archivePassEnabled }
        set { 
            if let appState { appState.settings.archivePassEnabled = newValue }
            _archivePassEnabled = newValue
            NotificationCenter.default.post(
                name: .archivePassEnabledChanged,
                object: nil,
                userInfo: ["enabled": newValue]
            )
        }
    }

    // Remaining ephemeral UI state
    public var autoRecordEnabled = false
    public var startDebounce = 3.0
    public var stopDebounce = 10.0
    public var defaultMeetingType: MeetingType = SummaryConfig.default.meetingType
    public var translationEnabled = false
    public var sourceLanguage = "en"
    public var targetLanguage = "es"
    public var cacheTTLHours = 24
    public var semanticCacheDays = 7
    public var maxCacheEntries = 1000
    public var defaultExportFormat: ShareFormat = .markdown
    public var speakerProfiles: [SpeakerProfile] = []
    public var errorMessage: String?
    public var buildID = "unknown"
    public var recentLogs: [String] = []

    // Integrations
    public var isNotionEnabled = false
    public var obsidianVaultPath = ""

    // Storage
    public var totalRecordingsBytes: Int64?
    public var availableDiskBytes: Int64?
    public var autoDeleteEnabled = false
    public var autoDeleteOlderThanDays: Int = 30

    public var deleteAllConfirmationText: String = ""
    public var isDeletingAllData: Bool = false
    public var deleteAllDataLog: [String] = []
    public var isRecordingActive: Bool = false

    // Audio device selection
    public var tapAllAudio = true
    public var echoCancellationEnabled = true
    public var outputDevices: [AudioDevice] = []
    public var inputDevices: [AudioDevice] = []
    public var selectedOutputDeviceID = ""
    public var selectedInputDeviceID = ""

    // Dependencies
    private let appState: AppState?
    let profileStore: (any SpeakerProfileStore)?
    let audioDeviceConfigStore: (any AudioDeviceConfigStore)?
    let deviceEnumeration: (any AudioDeviceEnumeration)?
    let recordingReadRepository: (any RecordingReadRepository)?
    let diskSpaceMonitor: (any DiskSpaceMonitor)?

    public init(
        appState: AppState? = nil,
        profileStore: (any SpeakerProfileStore)? = nil,
        audioDeviceConfigStore: (any AudioDeviceConfigStore)? = nil,
        deviceEnumeration: (any AudioDeviceEnumeration)? = nil,
        recordingReadRepository: (any RecordingReadRepository)? = nil,
        diskSpaceMonitor: (any DiskSpaceMonitor)? = nil
    ) {
        self.appState = appState
        self.profileStore = profileStore
        self.audioDeviceConfigStore = audioDeviceConfigStore
        self.deviceEnumeration = deviceEnumeration
        self.recordingReadRepository = recordingReadRepository
        self.diskSpaceMonitor = diskSpaceMonitor
    }

    public func loadCurrentTheme() {
        // Now handled by SSOT proxy
    }

    public func loadCurrentEngine() {
        // Now handled by SSOT proxy
    }

    public func saveEngine() {
        NotificationCenter.default.post(
            name: .engineChanged,
            object: nil,
            userInfo: ["defaultEngine": defaultEngine.rawValue]
        )
    }

    public func loadCurrentArchivePassEnabled() {
        // Now handled by SSOT proxy
    }

    public func saveTheme() {
        NotificationCenter.default.post(
            name: .themeChanged,
            object: nil,
            userInfo: ["uiTheme": uiTheme]
        )
    }

    public func applyPrivacyMode() {
        NotificationCenter.default.post(
            name: .privacyModeChanged,
            object: nil,
            userInfo: ["privacyMode": privacyMode.rawValue]
        )
    }

    public func refreshDiagnostics() {
        buildID = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String
            ?? Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String
            ?? "unknown"
        recentLogs = ErrorLog.shared.recentEntries
    }
}
